// Parse conversation management request
const requestData = JSON.parse($input.first().json.body);

// Determine conversation type
const conversationType = determineConversationType(requestData);

// Prepare conversation data
const conversationData = {
  type: conversationType,
  conversationId: requestData.conversationId || generateConversationId(),
  participants: requestData.participants || [],
  messages: requestData.messages || [],
  context: {
    campaign: requestData.campaign || {},
    environment: requestData.environment || {},
    session: requestData.session || {},
    previousConversations: requestData.previousConversations || []
  },
  metadata: {
    timestamp: new Date().toISOString(),
    source: 'dialogue-system',
    version: '1.0',
    priority: requestData.priority || 'normal'
  }
};

function determineConversationType(request) {
  if (request.action === 'initiate') return 'initiate';
  if (request.action === 'process') return 'process';
  if (request.action === 'conclude') return 'conclude';
  if (request.action === 'pause') return 'pause';
  if (request.action === 'resume') return 'resume';
  return 'process'; // default
}

function generateConversationId() {
  return 'conv_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
}

// Add action-specific data
if (requestData.action === 'initiate') {
  conversationData.initialContext = requestData.initialContext || {};
  conversationData.objectives = requestData.objectives || [];
} else if (requestData.action === 'process') {
  conversationData.newMessage = requestData.newMessage;
  conversationData.speakerId = requestData.speakerId;
  conversationData.additionalContext = requestData.additionalContext || {};
} else if (requestData.action === 'conclude') {
  conversationData.conclusionReason = requestData.reason || 'natural';
  conversationData.summary = requestData.summary || '';
}

return { json: conversationData };

// Process conversation results and generate comprehensive response
const originalData = items[0].json; // Original request data
const resultData = $input.first().json; // API response data

// Build unified response structure
const conversationResponse = {
  requestId: originalData.metadata.timestamp,
  conversationId: originalData.conversationId,
  action: originalData.type,
  success: resultData.success !== false,
  timestamp: new Date().toISOString(),
  data: {
    conversation: resultData.conversation || resultData,
    context: resultData.context || {},
    suggestions: resultData.suggestions || [],
    metadata: resultData.metadata || {}
  },
  analytics: {
    processingTime: resultData.processingTime || 0,
    messageCount: resultData.messages?.length || 0,
    participantCount: resultData.participants?.length || 0,
    emotionalState: resultData.emotionalState || {},
    topics: resultData.topics || []
  }
};

// Add action-specific data
if (originalData.type === 'initiate') {
  conversationResponse.data.openingSuggestions = resultData.suggestions?.openingLines || [];
  conversationResponse.data.initialContext = resultData.context?.initialContext || {};
} else if (originalData.type === 'process') {
  conversationResponse.data.responseSuggestions = resultData.suggestions || [];
  conversationResponse.data.messageAnalysis = {
    sentiment: resultData.sentiment || {},
    emotionalState: resultData.emotionalState || {},
    contextRelevance: resultData.contextRelevance || 0.5
  };
} else if (originalData.type === 'conclude') {
  conversationResponse.data.summary = resultData.summary || '';
  conversationResponse.data.analytics = resultData.analytics || {};
  conversationResponse.data.nextSteps = resultData.nextSteps || [];
}

// Add conversation state information
conversationResponse.state = {
  status: resultData.state || 'active',
  duration: resultData.duration || 0,
  lastActivity: resultData.lastActivity || new Date().toISOString(),
  nextActions: determineNextActions(originalData.type, resultData)
};

function determineNextActions(actionType, result) {
  const actions = [];

  switch (actionType) {
    case 'initiate':
      actions.push({
        type: 'send_message',
        suggested: true,
        description: 'Send first message to start conversation'
      });
      actions.push({
        type: 'set_emotional_tone',
        suggested: false,
        description: 'Set emotional tone for the conversation'
      });
      break;

    case 'process':
      actions.push({
        type: 'respond',
        suggested: true,
        description: 'Generate response to processed message'
      });
      actions.push({
        type: 'analyze_emotion',
        suggested: true,
        description: 'Analyze emotional content of message'
      });
      break;

    case 'conclude':
      actions.push({
        type: 'save_conversation',
        suggested: true,
        description: 'Save conversation to history'
      });
      actions.push({
        type: 'generate_summary',
        suggested: false,
        description: 'Generate detailed conversation summary'
      });
      break;
  }

  return actions;
}

return { json: conversationResponse };

// Prepare context update data
const response = $input.first().json;

const contextUpdate = {
  conversationId: response.conversationId,
  updates: {
    lastActivity: response.timestamp,
    participantEngagement: calculateEngagement(response.analytics),
    conversationHealth: assessConversationHealth(response.analytics),
    contextualElements: extractContextualElements(response.data)
  },
  metadata: {
    updateType: response.action,
    timestamp: response.timestamp,
    automated: true
  }
};

function calculateEngagement(analytics) {
  const messageCount = analytics.messageCount || 0;
  const participantCount = analytics.participantCount || 1;
  const avgMessagesPerParticipant = messageCount / participantCount;

  return {
    score: Math.min(1.0, avgMessagesPerParticipant / 10),
    messageCount,
    participantCount,
    averageMessagesPerParticipant: avgMessagesPerParticipant
  };
}

function assessConversationHealth(analytics) {
  const emotionalState = analytics.emotionalState || {};
  const emotionalIntensity = Object.values(emotionalState).reduce((sum, val) => sum + val, 0) / Object.keys(emotionalState).length;

  let healthScore = 0.5; // Base health

  // Positive emotions increase health
  if (emotionalState.happiness > 0.3) healthScore += 0.2;
  if (emotionalState.trust > 0.3) healthScore += 0.2;

  // Negative emotions decrease health
  if (emotionalState.anger > 0.5) healthScore -= 0.3;
  if (emotionalState.sadness > 0.5) healthScore -= 0.2;

  return {
    score: Math.max(0, Math.min(1, healthScore)),
    emotionalIntensity,
    dominantEmotion: Object.entries(emotionalState).sort((a, b) => b[1] - a[1])[0]?.[0] || 'neutral',
    needsAttention: healthScore < 0.3
  };
}

function extractContextualElements(data) {
  const elements = {
    topics: data.topics || [],
    emotionalTone: data.emotionalState || {},
    participants: data.participants || [],
    environment: data.environment || {},
    keyMoments: data.keyMoments || []
  };

  // Identify significant contextual elements
  elements.significant = {
    emotionalShifts: detectEmotionalShifts(data.emotionalState),
    topicChanges: detectTopicChanges(data.topics),
    participantChanges: detectParticipantChanges(data.participants)
  };

  return elements;
}

